package todo.hooks

import cats.effect.IO
import munit.CatsEffectSuite

import java.nio.file.{Files, Path, Paths}
import scala.sys.process.{Process, ProcessLogger}

/** Exercises the versioned `.githooks/pre-commit` hook and the
  * `just install-hooks` recipe against real, disposable git repositories —
  * a process/filesystem fixture, per `docs/rules/WOW.md`'s "no mocks" rule,
  * rather than unit-testing shell text.
  *
  * The two commit-outcome tests swap in a fixture `justfile` whose `check`
  * recipe is a one-line `exit <code>` instead of the real `sbt`-backed one,
  * so they assert the hook's pass-through behaviour (block on failure, allow
  * on success) in milliseconds instead of paying for a full `just check`.
  */
class PreCommitHookSuite extends CatsEffectSuite:

  private val repoRoot: Path         = Paths.get("").toAbsolutePath
  private val realHookScript: Path   = repoRoot.resolve(".githooks/pre-commit")
  private val realJustfile: Path     = repoRoot.resolve("justfile")
  private val realClaudeMd: Path     = repoRoot.resolve("CLAUDE.md")

  private case class Result(exitCode: Int, stdout: String, stderr: String)

  private def run(cwd: Path, cmd: String*): IO[Result] =
    IO.blocking {
      val out = new StringBuilder
      val err = new StringBuilder
      val logger = ProcessLogger(line => out.append(line).append('\n'), line => err.append(line).append('\n'))
      val exitCode = Process(cmd, cwd.toFile).!(logger)
      Result(exitCode, out.toString, err.toString)
    }

  private def freshGitRepo(): IO[Path] =
    for
      dir <- IO.blocking(Files.createTempDirectory("hook-fixture"))
      _ <- run(dir, "git", "init", "-q")
      _ <- run(dir, "git", "config", "user.email", "test@example.com")
      _ <- run(dir, "git", "config", "user.name", "Test")
    yield dir

  /** Installs the real hook script and a stub `justfile` whose `check`
    * recipe just exits with `checkExitCode`, then points git at it exactly
    * as `just install-hooks` would.
    */
  private def installHookWithStubbedCheck(dir: Path, checkExitCode: Int): IO[Unit] =
    IO.blocking {
      Files.createDirectories(dir.resolve(".githooks"))
      Files.copy(realHookScript, dir.resolve(".githooks/pre-commit"))
      dir.resolve(".githooks/pre-commit").toFile.setExecutable(true)
      Files.writeString(dir.resolve("justfile"), s"check:\n    exit $checkExitCode\n")
    }.flatMap(_ => run(dir, "git", "config", "core.hooksPath", ".githooks").void)

  private def attemptCommit(dir: Path): IO[Result] =
    for
      _ <- IO.blocking(Files.writeString(dir.resolve("file.txt"), "content"))
      _ <- run(dir, "git", "add", "file.txt")
      commit <- run(dir, "git", "commit", "-m", "test commit")
    yield commit

  test("the checked-in pre-commit hook script runs just check before a commit is created") {
    IO.blocking(Files.readString(realHookScript)).map { content =>
      assert(content.contains("just check"), s"expected the hook to invoke `just check`, was:\n$content")
    }
  }

  test("just install-hooks points git at .githooks and makes the hook executable") {
    for
      dir <- freshGitRepo()
      _ <- IO.blocking {
        Files.createDirectories(dir.resolve(".githooks"))
        Files.copy(realHookScript, dir.resolve(".githooks/pre-commit"))
        Files.copy(realJustfile, dir.resolve("justfile"))
      }
      install <- run(dir, "just", "install-hooks")
      hooksPath <- run(dir, "git", "config", "--get", "core.hooksPath")
      executable <- IO.blocking(Files.isExecutable(dir.resolve(".githooks/pre-commit")))
    yield
      assertEquals(install.exitCode, 0, install.stderr)
      assertEquals(hooksPath.stdout.trim, ".githooks")
      assert(executable)
  }

  test("a failing check is rejected by the hook: non-zero exit, no commit created") {
    for
      dir <- freshGitRepo()
      _ <- installHookWithStubbedCheck(dir, checkExitCode = 1)
      commit <- attemptCommit(dir)
      log <- run(dir, "git", "log", "--oneline")
    yield
      assertNotEquals(commit.exitCode, 0)
      assertEquals(log.stdout.trim, "")
  }

  test("a passing check lets the hook commit cleanly with no manual just check step") {
    for
      dir <- freshGitRepo()
      _ <- installHookWithStubbedCheck(dir, checkExitCode = 0)
      commit <- attemptCommit(dir)
      log <- run(dir, "git", "log", "--oneline")
    yield
      assertEquals(commit.exitCode, 0, commit.stderr)
      assert(log.stdout.trim.nonEmpty)
  }

  test("CLAUDE.md documents running just install-hooks once per clone") {
    IO.blocking(Files.readString(realClaudeMd)).map { content =>
      assert(content.contains("just install-hooks"))
    }
  }

